+++ b/tests/sites.test.js
@@ -0,0 +1,59 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const headers = { "X-Larder-Site": "annex" };
+
+function stocked() {
+  const fixture = app();
+  fixture.store.data.batches.push({ id: 10, itemId: 2, lot: "ANNEX", qty: 3, receivedOn: "2026-10-28", expires: "2026-10-29", location: "annex-fridge" });
+  fixture.store.data.seq.batch = 10;
+  return fixture;
+}
+
+test("sites scope stock reads and validate headers on shared routes", async () => {
+  const { handle } = stocked();
+  assert.equal((await handle({ path: "/items/2" })).body.onHand, 10);
+  const item = (await handle({ path: "/items/2", headers })).body;
+  assert.equal(item.onHand, 3);
+  assert.deepEqual(item.batches.map((b) => b.id), [10]);
+  assert.deepEqual((await handle({ path: "/batches", headers })).body.map((b) => b.id), [10]);
+  assert.equal((await handle({ path: "/batches/3", headers })).body.error.code, "unknown_batch");
+  assert.equal((await handle({ path: "/batches/10" })).status, 404);
+  assert.equal((await handle({ path: "/reports/stock-value", headers })).body.totalCents, 387);
+  const alerts = (await handle({ path: "/alerts", headers })).body;
+  assert.deepEqual(alerts.expiring.map((b) => b.id), [10]);
+  assert.equal(alerts.lowStock.find((i) => i.itemId === 2).qty, 3);
+  assert.equal((await handle({ path: "/dishes", headers })).body.length, 3);
+  const unknown = await handle({ path: "/suppliers", headers: { "x-larder-site": "missing" } });
+  assert.equal(unknown.status, 400);
+  assert.equal(unknown.body.error.code, "unknown_site");
+});
+
+test("cross-site waste and cooking cannot change stock or the ledger", async () => {
+  const { handle, store } = stocked();
+  const before = structuredClone(store.data);
+  assert.equal((await handle({ method: "POST", path: "/batches/3/waste", headers, body: { qty: 1 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: "/recipes/2/cook", headers, body: { portions: 10 } })).status, 409);
+  assert.deepEqual(store.data, before);
+  // Supply all ingredients locally, then cooking consumes only annex batches.
+  for (const itemId of [3, 4]) store.data.batches.push({ id: store.nextId("batch"), itemId, qty: 1, receivedOn: "2026-10-28", expires: null, location: "annex-fridge" });
+  const main = structuredClone(store.data.batches.filter((b) => b.id <= 9));
+  assert.equal((await handle({ method: "POST", path: "/recipes/2/cook", headers, body: { portions: 10 } })).status, 200);
+  assert.deepEqual(store.data.batches.filter((b) => b.id <= 9), main);
+  assert.equal(store.data.batches.find((b) => b.id === 10).qty, 1);
+});
+
+test("stock-takes are isolated and save changes in the shared store", async () => {
+  const { handle, store } = stocked();
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers, body: { location: "fridge" } })).status, 400);
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers, body: { location: "annex-fridge" } })).body;
+  for (const action of ["counts", "finish"]) {
+    assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/${action}`, body: { batchId: 10, counted: 2 } })).status, 404);
+  }
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers, body: { batchId: 3, counted: 2 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers, body: { batchId: 10, counted: 2 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers })).status, 200);
+  assert.equal(store.data.batches.find((b) => b.id === 10).qty, 2);
+  assert.equal(store.data.movements.at(-1).type, "adjust");
+});
